13	const state = {
14	  host: "",
15	  live: false,
16	  socket: null,
17	  stopped: false,
18	  justPaired: false,
19	  listRevision: -1,
20	  scope: null,
21	  sessions: [],
22	  projects: [],
23	  waitingIds: new Set(),
24	  open: null,
