51	// One request. The reply is the host's envelope: `body` on success,
52	// `error {code, message}` on a refusal.
53	async function api(method, path, body) {
54	  const init = { method, credentials: "same-origin", cache: "no-store", headers: {} };
55	  if (body !== undefined) {
56	    init.headers["Content-Type"] = "application/json";
57	    init.body = JSON.stringify(body);
58	  }
59	  let res;
60	  try {
61	    res = await fetch(path, init);
62	  } catch (e) {
63	    return { ok: false, status: 0, error: { message: "The host did not answer." } };
64	  }
65	  let json = {};
66	  try {
67	    json = await res.json();
68	  } catch (e) {
69	    json = {};
70	  }
71	  if (res.ok) {
72	    return { ok: true, status: res.status, body: json.body, revision: json.revision };
73	  }
74	  return {
75	    ok: false,
76	    status: res.status,
77	    error: json.error || { message: "The host answered " + res.status + "." },
78	  };
79	}
80	
81	// The invite is the URL's fragment. A browser never sends it, so the
82	// code reaches the host only in the pairing request. The URL is replaced
83	// before anything else runs, so the code leaves the address bar.
84	function readInvite() {
85	  const params = new URLSearchParams(location.hash.slice(1));
86	  if (!params.has("code") || !params.has("key") || !params.has("id")) {
87	    return null;
88	  }
89	  const invite = {
90	    code: (params.get("code") || "").toUpperCase(),
91	    key: params.get("key"),
92	    id: params.get("id"),
93	  };
94	  history.replaceState(null, "", "/");
95	  return invite;
96	}
97	
98	function deviceName() {
99	  const ua = navigator.userAgent;
100	  let browser = "Browser";
101	  if (/Edg\//.test(ua)) browser = "Edge";
102	  else if (/Chrome|CriOS|Chromium/.test(ua)) browser = "Chrome";
103	  else if (/Firefox|FxiOS/.test(ua)) browser = "Firefox";
104	  else if (/Safari/.test(ua)) browser = "Safari";
105	  let device = "computer";
106	  if (/iPhone/.test(ua)) device = "iPhone";
107	  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)) {
108	    device = "iPad";
109	  } else if (/Android/.test(ua)) device = "Android";
110	  else if (/Macintosh/.test(ua)) device = "Mac";
111	  return browser + " on " + device;
112	}
113	
114	function newOp() {
115	  const b = crypto.getRandomValues(new Uint8Array(16));
116	  b[6] = (b[6] & 0x0f) | 0x40;
117	  b[8] = (b[8] & 0x3f) | 0x80;
118	  const h = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
119	  return [h.slice(0, 8), h.slice(8, 12), h.slice(12, 16), h.slice(16, 20), h.slice(20)].join("-");
120	}
121	
122	// A refusal on an authenticated call: 401 ends the page's polling, and
123	// the words say which of the three ways it happened.
124	function failed(r) {
125	  if (r.status !== 401) {
126	    notice(r.error.message);
127	    return;
128	  }
129	  state.stopped = true;
130	  if (state.socket) state.socket.close();
131	  if (state.justPaired) {
132	    notice("This browser did not keep its pairing. Pair again.");
133	  } else if (readStored(STORE.server)) {
134	    notice("This device was revoked. Pair again.");
135	  } else {
136	    notice("Not paired. Open Remote devices on the Mac and scan the code.");
137	  }
138	}
139	
140	async function pair(invite, host) {
141	  const r = await api("POST", "/api/v1/pair", {
142	    code: invite.code,
143	    spki_sha256: invite.key,
144	    device_name: deviceName(),
145	    transport: "cookie",
146	  });
147	  if (!r.ok) {
148	    notice(r.error.message);
149	    return false;
150	  }
151	  writeStored(STORE.server, host.server_id);
152	  writeStored(STORE.key, invite.key);
153	  writeStored(STORE.scope, r.body.scope);
154	  state.justPaired = true;
155	  notice("");
156	  return true;
157	}
158	
159	async function boot() {
160	  const invite = readInvite();
161	  const info = await api("GET", "/api/v1/info");
162	  if (!info.ok) {
163	    notice(info.error.message);
164	    return;
165	  }
166	  const host = info.body;
167	  state.host = host.server_name;
168	  $("host").textContent = host.server_name;
169	  if (invite) {
170	    if (invite.key !== host.spki_sha256 || invite.id !== host.server_id) {
171	      notice("This is not the host whose code was scanned.");
172	      return;
173	    }
174	    if (!(await pair(invite, host))) return;
175	  } else if (
176	    readStored(STORE.server) === host.server_id &&
177	    readStored(STORE.key) !== host.spki_sha256
178	  ) {
179	    notice("This host's identity changed. Pair again.");
180	    return;
181	  }
182	  state.scope = readStored(STORE.scope);
183	  if (!readStored(STORE.server)) {
184	    notice("Not paired. Open Remote devices on the Mac and scan the code.");
185	    return;
186	  }
187	  await refreshList();
188	  setInterval(tick, 5000);
189	}
190	
191	// The list: the waiting call is the first authenticated request, so a
192	// pairing the host refused shows here. The socket opens after it, and
193	// the collections are fetched after the socket is up (subscribe first).
194	async function refreshList() {
195	  const waiting = await api("GET", "/api/v1/waiting");
196	  if (!waiting.ok) {
197	    failed(waiting);
198	    return;
199	  }
200	  state.justPaired = false;
201	  state.waitingIds = new Set(waiting.body.sessions.map((s) => s.id));
202	  let revision = waiting.revision;
203	  connectSocket();
204	  const projects = await api("GET", "/api/v1/projects");
205	  if (!projects.ok) {
206	    failed(projects);
207	    return;
208	  }
209	  const sessions = [];
210	  for (const p of projects.body.projects) {
211	    const list = await api("GET", "/api/v1/projects/" + p.id + "/sessions");
212	    if (!list.ok) {
213	      failed(list);
214	      return;
215	    }
216	    revision = Math.max(revision, list.revision);
217	    for (const s of list.body.sessions) {
218	      sessions.push(Object.assign({}, s, { projectName: p.name }));
219	    }
220	  }
221	  state.listRevision = Math.max(revision, projects.revision);
222	  state.projects = projects.body.projects;
223	  state.sessions = sessions;
224	  render();
225	}
226	
227	function render() {
228	  const list = $("list");
229	  list.replaceChildren();
230	  const groups = new Map();
231	  for (const s of state.sessions) {
232	    if (!groups.has(s.project)) groups.set(s.project, { name: s.projectName, items: [] });
233	    groups.get(s.project).items.push(s);
234	  }
235	  const isWaiting = (s) => s.waiting || state.waitingIds.has(s.id);
236	  const ordered = [...groups.values()]
237	    .map((g) => {
238	      g.items.sort((a, b) => Number(isWaiting(b)) - Number(isWaiting(a)));
239	      g.waiting = g.items.filter(isWaiting).length;
240	      return g;
241	    })
242	    .sort((a, b) => b.waiting - a.waiting || a.name.localeCompare(b.name));
243	  if (ordered.length === 0) {
244	    const p = document.createElement("p");
245	    p.className = "meta";
246	    p.textContent = "No sessions yet.";
247	    list.append(p);
248	  }
249	  for (const g of ordered) {
250	    const h = document.createElement("h2");
251	    h.textContent = g.name;
252	    list.append(h);
253	    for (const s of g.items) {
254	      const button = document.createElement("button");
255	      button.type = "button";
256	      button.className = "row" + (isWaiting(s) ? " waiting" : "");
257	      const name = document.createElement("span");
258	      name.className = "name";
259	      name.textContent = s.name;
260	      const meta = document.createElement("span");
261	      meta.className = "meta";
262	      meta.textContent = [s.kind, s.card, s.waiting_reason].filter(Boolean).join(" · ");
263	      button.append(name, meta);
264	      button.addEventListener("click", () => openSession(s));
265	      list.append(button);
266	    }
267	  }
268	  setStatus();
269	}
270	
271	function setStatus() {
272	  const scope = state.scope ? (state.scope === "control" ? "control" : "read-only") : "";
273	  $("status").textContent = [state.host, state.live ? "live" : "polling", scope]
274	    .filter(Boolean)
275	    .join(" · ");
276	}
277	
278	// The socket is an upgrade: the page works without it, polling the same
279	// collections, and the socket's events only say what to refetch.
280	function connectSocket() {
281	  if (state.socket || state.stopped) return;
282	  let ws;
283	  try {
284	    ws = new WebSocket("wss://" + location.host + "/api/v1/events");
285	  } catch (e) {
286	    return;
287	  }
288	  state.socket = ws;
289	  ws.onmessage = (m) => {
290	    let ev;
291	    try {
292	      ev = JSON.parse(m.data);
293	    } catch (e) {
294	      return;
295	    }
296	    onEvent(ev);
297	  };
298	  ws.onclose = () => {
299	    if (state.socket === ws) state.socket = null;
300	    state.live = false;
301	    setStatus();
302	  };
303	}
304	
305	function sendFrame(type, open) {
306	  if (state.socket && state.socket.readyState === WebSocket.OPEN) {
307	    state.socket.send(JSON.stringify({ type, resource: { kind: open.contentKind, id: open.id } }));
308	  }
309	}
310	
311	function onEvent(ev) {
312	  if (ev.type === "hello") {
313	    state.live = true;
314	    setStatus();
315	    if (state.open) sendFrame("watch", state.open);
316	    refreshList();
317	    return;
318	  }
319	  if (ev.type === "resync_required") {
320	    if (state.socket) state.socket.close();
321	    return;
322	  }
323	  const kind = ev.resource ? ev.resource.kind : "";
324	  const id = ev.resource ? ev.resource.id : "";
325	  if (ev.type === "watching") {
326	    if (state.open && id === state.open.id && kind === state.open.contentKind) loadOpen();
327	    return;
328	  }
329	  if (ev.type !== "changed" && ev.type !== "removed") return;
330	  if (kind === "conversation" || kind === "screen") {
331	    if (state.open && id === state.open.id && ev.revision > state.open.revision) loadOpen();
332	    return;
333	  }
334	  if (ev.revision > state.listRevision) refreshList();
335	}
336	
337	// Polling while the socket is down, and the socket retried every 30 s.
338	function tick() {
339	  if (state.stopped) return;
340	  state.ticks += 1;
341	  if (!state.live) {
342	    refreshList();
343	    if (state.open) loadOpen();
344	  }
345	  if (state.ticks % 6 === 0) connectSocket();
346	}
347	
348	async function openSession(s) {
349	  closeOpen();
350	  state.open = {
351	    id: s.id,
352	    name: s.name,
353	    contentKind: s.kind === "claude" ? "conversation" : "screen",
354	    revision: -1,
355	  };
356	  $("list").hidden = true;
357	  $("session").hidden = false;
358	  $("session-name").textContent = s.name;
359	  $("session-text").textContent = "";
360	  $("reply-note").textContent = "";
361	  renderReplyBox();
362	  if (state.socket && state.socket.readyState === WebSocket.OPEN) {
363	    sendFrame("watch", state.open);
364	  } else {
365	    loadOpen();
366	  }
367	}
368	
369	function closeOpen() {
370	  if (state.open) sendFrame("unwatch", state.open);
371	  state.open = null;
372	}
373	
374	async function loadOpen() {
375	  const open = state.open;
376	  if (!open) return;
377	  const path =
378	    open.contentKind === "conversation"
379	      ? "/api/v1/sessions/" + open.id + "/last-response"
380	      : "/api/v1/sessions/" + open.id + "/screen";
381	  const r = await api("GET", path);
382	  if (state.open !== open) return;
383	  if (!r.ok) {
384	    failed(r);
385	    return;
386	  }
387	  open.revision = r.revision;
388	  const text = r.body.text || (open.contentKind === "conversation" ? "No response yet." : "");
389	  $("session-text").textContent = text;
390	}
391	
392	function renderReplyBox() {
393	  $("reply").hidden = !(state.open && state.scope === "control");
394	}
395	
396	$("back").addEventListener("click", () => {
397	  closeOpen();
398	  $("session").hidden = true;
399	  $("list").hidden = false;
400	});
401	
402	$("reply").addEventListener("submit", async (ev) => {
403	  ev.preventDefault();
404	  const open = state.open;
405	  const text = $("reply-text").value.trim();
406	  if (!open || text === "") return;
407	  const r = await api("POST", "/api/v1/sessions/" + open.id + "/send", { op: newOp(), text });
408	  if (state.open !== open) return;
409	  if (r.ok) {
410	    $("reply-text").value = "";
411	    $("reply-note").textContent = "Sent.";
412	    loadOpen();
413	  } else if (r.status === 403) {
414	    state.scope = "read";
415	    writeStored(STORE.scope, "read");
416	    renderReplyBox();
417	    setStatus();
418	    $("reply-note").textContent = "This device is read-only now.";
419	  } else {
420	    failed(r);
421	    $("reply-note").textContent = r.error.message;
422	  }
423	});
424	
425	boot();
426

