//! The Remote devices dialog: who this host is to a device, where it
//! listens, the pairing window with its QR code, and the devices paired
//! so far with their scope and a Revoke. Nothing here decides anything:
//! every change is an action, and the host's state is read back from
//! the core each frame.

use egui::{Context, RichText, Ui};

use super::{DrawCtx, GAP, cards::since_text, theme};
use crate::adapters::remote;
use crate::core::{AppAction, AppCore};
use crate::ports::remote::Scope;

/// What the dialog edits between frames: the name and port fields, the
/// scope the next pairing grants, and the QR image for the open code.
pub struct RemoteDraft {
    pub name: String,
    pub port: String,
    pub scope: Scope,
    /// The QR texture for the code it was made for.
    qr: Option<(String, egui::TextureHandle)>,
}

impl RemoteDraft {
    #[must_use]
    pub fn open(core: &AppCore) -> Self {
        let identity = core.identity();
        Self {
            name: identity.map(|i| i.server_name.clone()).unwrap_or_default(),
            port: identity
                .map(|i| i.listen.port.to_string())
                .unwrap_or_default(),
            scope: Scope::Read,
            qr: None,
        }
    }
}

/// The dialog's width: the QR and the device rows fit it.
const DIALOG_WIDTH: f32 = 620.0;
/// Pixels per QR module; the quiet zone is the standard four.
const QR_SCALE: usize = 4;
const QR_QUIET: usize = 4;

pub fn show(cx: &mut DrawCtx<'_>, ctx: &Context) {
    let Some(mut draft) = cx.state.remote_dialog.take() else {
        return;
    };
    let mut keep = true;
    egui::Window::new("")
        .id(egui::Id::new("remote-devices"))
        .title_bar(false)
        .collapsible(false)
        .resizable(true)
        .default_width(DIALOG_WIDTH)
        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
        .show(ctx, |ui| {
            let screen = ctx.content_rect().width();
            ui.set_max_width((screen - 80.0).clamp(320.0, DIALOG_WIDTH));
            ui.spacing_mut().item_spacing = egui::vec2(GAP, GAP);
            ui.label(RichText::new("Remote devices").text_style(theme::brand()));
            ui.add_space(8.0);
            host(cx, ui, &mut draft);
            ui.add_space(8.0);
            pairing(cx, ui, &mut draft);
            ui.add_space(8.0);
            devices(cx, ui);
            ui.add_space(8.0);
            let p = theme::palette(ui);
            ui.label(
                RichText::new(
                    "What a device reads is redacted: the values of a project's secret variables and of its granted sets are replaced by their names. A secret pasted into a prompt, or printed by a tool, that Switchboard never held is not found.",
                )
                .small()
                .color(p.n600),
            );
            ui.horizontal(|ui| {
                if theme::ghost_muted(ui, "Close").clicked() {
                    keep = false;
                }
            });
        });
    if keep {
        cx.state.remote_dialog = Some(draft);
    }
}

/// This host: its name, id and key, and where it listens.
fn host(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
    theme::section(ui, "This Mac");
    let Some(identity) = cx.core.identity().cloned() else {
        ui.label("The host has no identity yet; see the log.");
        return;
    };
    ui.horizontal(|ui| {
        let id = ui.label("Name").id;
        let field = ui
            .add(egui::TextEdit::singleline(&mut draft.name).desired_width(240.0))
            .labelled_by(id);
        if field.lost_focus() && draft.name.trim() != identity.server_name {
            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
        }
    });
    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
    ui.label(theme::meta_text(
        ui,
        format!("Key {}", short_hash(&identity.spki_sha256)),
    ));
    ui.horizontal(|ui| {
        let mut lan = identity.listen.lan;
        if ui
            .checkbox(&mut lan, "Allow devices on the local network")
            .on_hover_text("Off, the port answers this Mac alone; on, it listens on every interface and only paired devices get past /info")
            .changed()
        {
            cx.dispatch(AppAction::SetRemoteListen {
                lan,
                port: identity.listen.port,
            });
        }
        let id = ui.label("Port").id;
        let field = ui
            .add(egui::TextEdit::singleline(&mut draft.port).desired_width(64.0))
            .labelled_by(id);
        if field.lost_focus() {
            match draft.port.trim().parse::<u16>() {
                Ok(port) if port != 0 && port != identity.listen.port => {
                    cx.dispatch(AppAction::SetRemoteListen {
                        lan: identity.listen.lan,
                        port,
                    });
                }
                Ok(_) => {}
                Err(_) => draft.port = identity.listen.port.to_string(),
            }
        }
    });
}

/// The pairing window: open it with a scope, or show the code it holds.
fn pairing(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
    theme::section(ui, "Pairing");
    let p = theme::palette(ui);
    if cx.core.identity_rotated() {
        ui.label(
            RichText::new(
                "The host's key was remade at this launch, so every earlier pairing is invalid. Pair each device again.",
            )
            .color(p.accent_2_text),
        );
    }
    let Some(identity) = cx.core.identity().cloned() else {
        return;
    };
    if let Some(window) = cx.core.pairing().cloned() {
        let port = cx.remote_port.unwrap_or(identity.listen.port);
        // Without a network address there is no URL to hand a phone: the
        // code and the full key are shown for the command-line form.
        let address = remote::local_address().map(|ip| format!("{ip}:{port}"));
        let invite = address
            .as_deref()
            .map(|a| crate::core::remote::pairing_invite(&identity, a, &window.code));
        if let Some(invite) = &invite
            && draft
                .qr
                .as_ref()
                .is_none_or(|(code, _)| *code != window.code)
        {
            draft.qr = qr_texture(ui.ctx(), invite).map(|t| (window.code.clone(), t));
        }
        ui.horizontal(|ui| {
            if let Some((_, texture)) = &draft.qr {
                ui.image(egui::load::SizedTexture::from_handle(texture));
            }
            ui.vertical(|ui| {
                ui.label(
                    RichText::new(spaced(&window.code))
                        .text_style(theme::h1())
                        .family(egui::FontFamily::Monospace),
                );
                let key = if address.is_some() {
                    short_hash(&identity.spki_sha256)
                } else {
                    identity.spki_sha256.clone()
                };
                ui.label(theme::meta_text(ui, format!("Key {key}")));
                if let Some(address) = &address {
                    ui.label(theme::meta_text(ui, format!("Address {address}")));
                }
                let sentence = if address.is_some() {
                    "Scan with a phone's camera, or paste the invite into a client. The browser will warn about the certificate: on your own network, accepting it is the trust step, and it may ask again."
                } else {
                    "No network address: pair by `switchboard-remote pair <host:port> <code> <key>`."
                };
                ui.label(theme::meta_text(
                    ui,
                    format!(
                        "{sentence} Grants {} scope. Open for five minutes or three wrong codes.",
                        window.scope.word()
                    ),
                ));
                ui.horizontal(|ui| {
                    // The QR's text, for a client without a camera (the
                    // command-line browser takes it as one argument).
                    if let Some(invite) = &invite
                        && theme::secondary(ui, "Copy invite")
                            .on_hover_text("The QR code's text: the address a phone opens")
                            .clicked()
                    {
                        ui.ctx().copy_text(invite.clone());
                    }
                    if theme::secondary(ui, "Stop pairing").clicked() {
                        cx.dispatch(AppAction::ClosePairing);
                    }
                });
            });
        });
    } else {
        ui.horizontal(|ui| {
            ui.radio_value(&mut draft.scope, Scope::Read, "Read-only")
                .on_hover_text("Every view and the screen; nothing is sent into a session");
            ui.radio_value(&mut draft.scope, Scope::Control, "Control")
                .on_hover_text("Reads, and later the commands that type into a session");
            if theme::primary(ui, "Allow pairing for 5 minutes").clicked() {
                cx.dispatch(AppAction::OpenPairing {
                    code: remote::pairing_code(),
                    scope: draft.scope,
                });
            }
        });
    }
}

/// The devices paired so far, each with its scope and a Revoke.
fn devices(cx: &mut DrawCtx<'_>, ui: &mut Ui) {
    theme::section(ui, "Paired devices");
    let devices = cx.core.devices().to_vec();
    if devices.is_empty() {
        ui.label(theme::meta_text(ui, "No device is paired."));
        return;
    }
    egui::Grid::new("remote-devices")
        .num_columns(5)
        .spacing([GAP, GAP])
        .show(ui, |ui| {
            for device in devices {
                ui.label(&device.name);
                let mut scope = device.scope;
                egui::ComboBox::from_id_salt(("remote-scope", device.id))
                    .selected_text(scope.word())
                    .show_ui(ui, |ui| {
                        ui.selectable_value(&mut scope, Scope::Read, "read");
                        ui.selectable_value(&mut scope, Scope::Control, "control");
                    });
                if scope != device.scope {
                    cx.dispatch(AppAction::SetDeviceScope {
                        device: device.id,
                        scope,
                    });
                }
                ui.label(theme::meta_text(
                    ui,
                    format!("paired {}", since_text(device.created)),
                ));
                ui.label(theme::meta_text(
                    ui,
                    match device.last_seen {
                        Some(seen) => format!("seen {}", since_text(seen)),
                        None => "never seen".into(),
                    },
                ));
                if theme::ghost_muted(ui, "Revoke")
                    .on_hover_text("The device's next request fails; pair it again to restore it")
                    .clicked()
                {
                    cx.dispatch(AppAction::RevokeDevice(device.id));
                }
                ui.end_row();
            }
        });
}

/// The QR code for `payload` as a texture: black modules on white with
/// the quiet zone, scaled so a phone reads it from the screen.
fn qr_texture(ctx: &Context, payload: &str) -> Option<egui::TextureHandle> {
    let code = qrcode::QrCode::new(payload.as_bytes()).ok()?;
    let width = code.width();
    let modules = code.to_colors();
    let side = (width + 2 * QR_QUIET) * QR_SCALE;
    let mut pixels = vec![egui::Color32::WHITE; side * side];
    for (i, module) in modules.iter().enumerate() {
        if *module != qrcode::Color::Dark {
            continue;
        }
        let (x, y) = (i % width + QR_QUIET, i / width + QR_QUIET);
        for dy in 0..QR_SCALE {
            for dx in 0..QR_SCALE {
                pixels[(y * QR_SCALE + dy) * side + x * QR_SCALE + dx] = egui::Color32::BLACK;
            }
        }
    }
    let image = egui::ColorImage::new([side, side], pixels);
    Some(ctx.load_texture("remote-pairing-qr", image, egui::TextureOptions::NEAREST))
}

/// The first sixteen hex digits of a key hash in groups of four: what
/// a person compares against the client's screen.
fn short_hash(hex: &str) -> String {
    hex.chars()
        .take(16)
        .collect::<Vec<_>>()
        .chunks(4)
        .map(|c| c.iter().collect::<String>())
        .collect::<Vec<_>>()
        .join(" ")
}

/// "ABCD EFGH": the code in two halves, as it is read aloud.
fn spaced(code: &str) -> String {
    let (a, b) = code.split_at(code.len() / 2);
    format!("{a} {b}")
}

"use strict";

// The token is not here. The host set it as an HttpOnly cookie that
// script cannot read, and the browser sends it with every request to
// this host. What is kept is public: which host this is, its key hash
// (to see an identity change) and the scope the pairing granted.
const STORE = {
  server: "switchboard.server_id",
  key: "switchboard.spki_sha256",
  scope: "switchboard.scope",
};

const state = {
  host: "",
  live: false,
  socket: null,
  stopped: false,
  justPaired: false,
  listRevision: -1,
  scope: null,
  sessions: [],
  projects: [],
  waitingIds: new Set(),
  open: null,
  ticks: 0,
};

const $ = (id) => document.getElementById(id);

function readStored(name) {
  try {
    return localStorage.getItem(name);
  } catch (e) {
    return null;
  }
}

function writeStored(name, value) {
  try {
    localStorage.setItem(name, value);
  } catch (e) {
    // Private browsing: this visit still works, the next one pairs again.
  }
}

function notice(text) {
  $("notice").textContent = text;
  $("notice").hidden = text === "";
}

// One request. The reply is the host's envelope: `body` on success,
// `error {code, message}` on a refusal.
async function api(method, path, body) {
  const init = { method, credentials: "same-origin", cache: "no-store", headers: {} };
  if (body !== undefined) {
    init.headers["Content-Type"] = "application/json";
    init.body = JSON.stringify(body);
  }
  let res;
  try {
    res = await fetch(path, init);
  } catch (e) {
    return { ok: false, status: 0, error: { message: "The host did not answer." } };
  }
  let json = {};
  try {
    json = await res.json();
  } catch (e) {
    json = {};
  }
  if (res.ok) {
    return { ok: true, status: res.status, body: json.body, revision: json.revision };
  }
  return {
    ok: false,
    status: res.status,
    error: json.error || { message: "The host answered " + res.status + "." },
  };
}

// The invite is the URL's fragment. A browser never sends it, so the
// code reaches the host only in the pairing request. The URL is replaced
// before anything else runs, so the code leaves the address bar.
function readInvite() {
  const params = new URLSearchParams(location.hash.slice(1));
  if (!params.has("code") || !params.has("key") || !params.has("id")) {
    return null;
  }
  const invite = {
    code: (params.get("code") || "").toUpperCase(),
    key: params.get("key"),
    id: params.get("id"),
  };
  history.replaceState(null, "", "/");
  return invite;
}

function deviceName() {
  const ua = navigator.userAgent;
  let browser = "Browser";
  if (/Edg\//.test(ua)) browser = "Edge";
  else if (/Chrome|CriOS|Chromium/.test(ua)) browser = "Chrome";
  else if (/Firefox|FxiOS/.test(ua)) browser = "Firefox";
  else if (/Safari/.test(ua)) browser = "Safari";
  let device = "computer";
  if (/iPhone/.test(ua)) device = "iPhone";
  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)) {
    device = "iPad";
  } else if (/Android/.test(ua)) device = "Android";
  else if (/Macintosh/.test(ua)) device = "Mac";
  return browser + " on " + device;
}

function newOp() {
  const b = crypto.getRandomValues(new Uint8Array(16));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  return [h.slice(0, 8), h.slice(8, 12), h.slice(12, 16), h.slice(16, 20), h.slice(20)].join("-");
}

// A refusal on an authenticated call: 401 ends the page's polling, and
// the words say which of the three ways it happened.
function failed(r) {
  if (r.status !== 401) {
    notice(r.error.message);
    return;
  }
  state.stopped = true;
  if (state.socket) state.socket.close();
  if (state.justPaired) {
    notice("This browser did not keep its pairing. Pair again.");
  } else if (readStored(STORE.server)) {
    notice("This device was revoked. Pair again.");
  } else {
    notice("Not paired. Open Remote devices on the Mac and scan the code.");
  }
}

async function pair(invite, host) {
  const r = await api("POST", "/api/v1/pair", {
    code: invite.code,
    spki_sha256: invite.key,
    device_name: deviceName(),
    transport: "cookie",
  });
  if (!r.ok) {
    notice(r.error.message);
    return false;
  }
  writeStored(STORE.server, host.server_id);
  writeStored(STORE.key, invite.key);
  writeStored(STORE.scope, r.body.scope);
  state.justPaired = true;
  notice("");
  return true;
}

async function boot() {
  const invite = readInvite();
  const info = await api("GET", "/api/v1/info");
  if (!info.ok) {
    notice(info.error.message);
    return;
  }
  const host = info.body;
  state.host = host.server_name;
  $("host").textContent = host.server_name;
  if (invite) {
    if (invite.key !== host.spki_sha256 || invite.id !== host.server_id) {
      notice("This is not the host whose code was scanned.");
      return;
    }
    if (!(await pair(invite, host))) return;
  } else if (
    readStored(STORE.server) === host.server_id &&
    readStored(STORE.key) !== host.spki_sha256
  ) {
    notice("This host's identity changed. Pair again.");
    return;
  }
  state.scope = readStored(STORE.scope);
  if (!readStored(STORE.server)) {
    notice("Not paired. Open Remote devices on the Mac and scan the code.");
    return;
  }
  await refreshList();
  setInterval(tick, 5000);
}

// The list: the waiting call is the first authenticated request, so a
// pairing the host refused shows here. The socket opens after it, and
// the collections are fetched after the socket is up (subscribe first).
async function refreshList() {
  const waiting = await api("GET", "/api/v1/waiting");
  if (!waiting.ok) {
    failed(waiting);
    return;
  }
  state.justPaired = false;
  state.waitingIds = new Set(waiting.body.sessions.map((s) => s.id));
  let revision = waiting.revision;
  connectSocket();
  const projects = await api("GET", "/api/v1/projects");
  if (!projects.ok) {
    failed(projects);
    return;
  }
  const sessions = [];
  for (const p of projects.body.projects) {
    const list = await api("GET", "/api/v1/projects/" + p.id + "/sessions");
    if (!list.ok) {
      failed(list);
      return;
    }
    revision = Math.max(revision, list.revision);
    for (const s of list.body.sessions) {
      sessions.push(Object.assign({}, s, { projectName: p.name }));
    }
  }
  state.listRevision = Math.max(revision, projects.revision);
  state.projects = projects.body.projects;
  state.sessions = sessions;
  render();
}

function render() {
  const list = $("list");
  list.replaceChildren();
  const groups = new Map();
  for (const s of state.sessions) {
    if (!groups.has(s.project)) groups.set(s.project, { name: s.projectName, items: [] });
    groups.get(s.project).items.push(s);
  }
  const isWaiting = (s) => s.waiting || state.waitingIds.has(s.id);
  const ordered = [...groups.values()]
    .map((g) => {
      g.items.sort((a, b) => Number(isWaiting(b)) - Number(isWaiting(a)));
      g.waiting = g.items.filter(isWaiting).length;
      return g;
    })
    .sort((a, b) => b.waiting - a.waiting || a.name.localeCompare(b.name));
  if (ordered.length === 0) {
    const p = document.createElement("p");
    p.className = "meta";
    p.textContent = "No sessions yet.";
    list.append(p);
  }
  for (const g of ordered) {
    const h = document.createElement("h2");
    h.textContent = g.name;
    list.append(h);
    for (const s of g.items) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "row" + (isWaiting(s) ? " waiting" : "");
      const name = document.createElement("span");
      name.className = "name";
      name.textContent = s.name;
      const meta = document.createElement("span");
      meta.className = "meta";
      meta.textContent = [s.kind, s.card, s.waiting_reason].filter(Boolean).join(" · ");
      button.append(name, meta);
      button.addEventListener("click", () => openSession(s));
      list.append(button);
    }
  }
  setStatus();
}

function setStatus() {
  const scope = state.scope ? (state.scope === "control" ? "control" : "read-only") : "";
